async function get(url) {
  try {
    return await load(url);
  } catch {
    return get(url);
  }
}

async function get(url, n = 0) {
  try { return await load(url); }
  catch (e) {
    if (n >= 3) throw e;
    await sleep(2 ** n * 500
      + Math.random() * 500);
    return get(url, n + 1);
  }
}

